DROP TABLE IF EXISTS god2_research._xjz_stage_monster_stat_probe_priority_rule;

CREATE TABLE god2_research._xjz_stage_monster_observation_tool_template (
  item_id INT PRIMARY KEY,
  name_zh_tw VARCHAR(160) NOT NULL,
  category VARCHAR(32) NOT NULL,
  subcategory VARCHAR(32),
  tool_group VARCHAR(96) NOT NULL,
  observation_kind VARCHAR(96) NOT NULL,
  observed_monster_field VARCHAR(96) NOT NULL,
  server_apply_table VARCHAR(96) NOT NULL,
  service_handler_hint VARCHAR(128) NOT NULL,
  effect_code VARCHAR(64),
  general_use INT,
  battle_use INT,
  use_on_other INT,
  description_json LONGTEXT,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_monster_observation_capture_target (
  target_id INT PRIMARY KEY,
  item_id INT NOT NULL,
  name_zh_tw VARCHAR(160) NOT NULL,
  tool_group VARCHAR(96) NOT NULL,
  observation_kind VARCHAR(96) NOT NULL,
  observed_monster_field VARCHAR(96) NOT NULL,
  target_sample_table VARCHAR(96) NOT NULL,
  target_event_table VARCHAR(96) NOT NULL,
  action_key VARCHAR(96) NOT NULL,
  capture_priority VARCHAR(32) NOT NULL,
  required_player_action_zh_tw TEXT NOT NULL,
  wanted_fields_json LONGTEXT,
  reverse_probe_value VARCHAR(128) NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_monster_stat_reverse_probe_source (
  source_id INT PRIMARY KEY,
  source_kind VARCHAR(96) NOT NULL,
  source_ref_id INT,
  source_name_zh_tw VARCHAR(160) NOT NULL,
  probe_group VARCHAR(96) NOT NULL,
  probe_strength VARCHAR(96) NOT NULL,
  direct_monster_stat_apply INT NOT NULL,
  derived_monster_fields_json LONGTEXT,
  capture_tables_json LONGTEXT,
  route_tables_json LONGTEXT,
  server_apply_hint TEXT NOT NULL,
  source_table VARCHAR(128) NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_monster_stat_probe_priority_rule (
  rule_id INT PRIMARY KEY,
  source_id INT NOT NULL,
  priority_rank INT NOT NULL,
  source_kind VARCHAR(96) NOT NULL,
  source_ref_id INT,
  source_name_zh_tw VARCHAR(160) NOT NULL,
  probe_group VARCHAR(96) NOT NULL,
  probe_strength VARCHAR(96) NOT NULL,
  apply_phase VARCHAR(96) NOT NULL,
  primary_target_table VARCHAR(96) NOT NULL,
  server_handler_key VARCHAR(128) NOT NULL,
  direct_apply_to_monster_template INT NOT NULL,
  requires_official_sample INT NOT NULL,
  wanted_fields_json LONGTEXT,
  capture_tables_json LONGTEXT,
  route_tables_json LONGTEXT,
  source_table VARCHAR(128) NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

