INSERT INTO god2_research._xjz_stage_monster_stat_probe_priority_rule
SELECT
    source_id,
    source_id,
    CASE
        WHEN source_kind = 'monster_stat_playbook_group' THEN 5
        WHEN probe_strength = 'direct_hp_capture' THEN 10
        WHEN probe_strength = 'special_enemy_hp_capture' THEN 15
        WHEN probe_strength = 'level_and_capture_rule_probe' THEN 20
        WHEN probe_strength = 'card_identity_probe' THEN 30
        WHEN probe_strength = 'static_card_stat_and_identity_probe' THEN 35
        WHEN probe_strength = 'encounter_distribution_probe' THEN 40
        WHEN probe_group = 'monster_visual_identity' THEN 45
        WHEN source_kind = 'combat_skill_runtime_group' THEN 50
        WHEN probe_strength = 'runtime_probe' THEN 60
        WHEN probe_strength = 'bundle_to_observation_tool' THEN 80
        ELSE 90
    END,
    source_kind,
    source_ref_id,
    source_name_zh_tw,
    probe_group,
    probe_strength,
    CASE
        WHEN source_kind = 'monster_stat_playbook_group' THEN 'official_stat_capture_route'
        WHEN probe_strength = 'direct_hp_capture' THEN 'normal_enemy_hp_sample'
        WHEN probe_strength = 'special_enemy_hp_capture' THEN 'special_enemy_hp_sample'
        WHEN probe_strength = 'level_and_capture_rule_probe' THEN 'monster_level_boundary_sample'
        WHEN probe_strength = 'card_identity_probe' THEN 'change_doll_identity_sample'
        WHEN probe_strength = 'static_card_stat_and_identity_probe' THEN 'change_doll_static_stat_reference'
        WHEN probe_strength = 'encounter_distribution_probe' THEN 'map_encounter_distribution_sample'
        WHEN probe_group = 'monster_visual_identity' THEN 'monster_visual_identity_binding'
        WHEN source_kind = 'combat_skill_runtime_group' THEN 'combat_formula_and_skill_sample'
        WHEN probe_strength = 'runtime_probe' THEN 'runtime_observation_sample'
        WHEN probe_strength = 'bundle_to_observation_tool' THEN 'observation_tool_bundle_unlock'
        ELSE 'manual_review_sample'
    END,
    CASE
        WHEN probe_strength = 'direct_hp_capture' THEN 'monster_stat_capture'
        WHEN probe_strength = 'special_enemy_hp_capture' THEN 'monster_stat_capture'
        WHEN probe_strength = 'level_and_capture_rule_probe' THEN 'combat_pet_capture_rule_sample'
        WHEN probe_strength = 'encounter_distribution_probe' THEN 'map_encounter_sample'
        WHEN probe_strength = 'card_identity_probe' THEN 'change_doll_apply_sample'
        WHEN probe_strength = 'static_card_stat_and_identity_probe' THEN 'change_doll_card_stats'
        WHEN probe_group = 'monster_visual_identity' THEN 'monster_visual_template'
        WHEN source_kind = 'combat_skill_runtime_group' THEN 'combat_formula_sample'
        WHEN probe_strength = 'bundle_to_observation_tool' THEN 'loot_or_choice_pool'
        ELSE source_table
    END,
    CASE
        WHEN probe_strength = 'direct_hp_capture' THEN 'monster_hp_observation_handler'
        WHEN probe_strength = 'special_enemy_hp_capture' THEN 'special_enemy_hp_observation_handler'
        WHEN probe_strength = 'level_and_capture_rule_probe' THEN 'monster_seal_level_probe_handler'
        WHEN probe_strength = 'encounter_distribution_probe' THEN 'map_encounter_distribution_handler'
        WHEN probe_strength = 'card_identity_probe' THEN 'change_doll_identity_probe_handler'
        WHEN probe_strength = 'static_card_stat_and_identity_probe' THEN 'change_doll_static_stat_reference_handler'
        WHEN probe_group = 'monster_visual_identity' THEN 'monster_visual_identity_handler'
        WHEN source_kind = 'combat_skill_runtime_group' THEN 'combat_runtime_probe_handler'
        WHEN probe_strength = 'bundle_to_observation_tool' THEN 'observation_bundle_open_handler'
        WHEN source_kind = 'monster_stat_playbook_group' THEN 'monster_stat_official_capture_route_handler'
        ELSE 'monster_runtime_observation_handler'
    END,
    0,
    1,
    derived_monster_fields_json,
    capture_tables_json,
    route_tables_json,
    source_table,
    raw_source,
    raw_line,
    'client_monster_stat_probe_priority_rule',
    packet_evidence_boundary
FROM god2_research._xjz_stage_monster_stat_reverse_probe_source;

CREATE TABLE IF NOT EXISTS god2_research.xjz_monster_observation_tool_evidence (
  item_id INT NOT NULL,
  item_name_zh_tw VARCHAR(160) NOT NULL,
  tool_type_zh_tw VARCHAR(96) NOT NULL,
  observation_function_zh_tw VARCHAR(160) NOT NULL,
  observed_monster_field_zh_tw VARCHAR(160) NOT NULL,
  target_runtime_table_zh_tw VARCHAR(160) NOT NULL,
  service_handler_hint_zh_tw VARCHAR(160) NOT NULL,
  usable_in_general INT NULL,
  usable_in_battle INT NULL,
  usable_on_other INT NULL,
  description_zh_tw TEXT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(128) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (item_id),
  KEY ix_xjz_monster_observation_field (observed_monster_field_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：怪物觀測道具與可觀測能力欄位，包含HP/MP/能力逆推入口。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_monster_observation_capture_targets (
  target_id INT NOT NULL,
  item_id INT NOT NULL,
  item_name_zh_tw VARCHAR(160) NOT NULL,
  observation_function_zh_tw VARCHAR(160) NOT NULL,
  observed_monster_field_zh_tw VARCHAR(160) NOT NULL,
  target_sample_table_zh_tw VARCHAR(160) NOT NULL,
  target_event_table_zh_tw VARCHAR(160) NOT NULL,
  action_key_zh_tw VARCHAR(160) NOT NULL,
  capture_priority_zh_tw VARCHAR(32) NOT NULL,
  required_player_action_zh_tw TEXT NOT NULL,
  wanted_fields_zh_tw TEXT NOT NULL,
  reverse_probe_value_zh_tw VARCHAR(160) NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(128) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (target_id),
  KEY ix_xjz_monster_observation_target_item (item_id),
  KEY ix_xjz_monster_observation_target_field (observed_monster_field_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：怪物HP/MP/能力抓包與黑箱測試目標。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_monster_stat_reverse_probe_sources (
  source_id INT NOT NULL,
  source_kind_zh_tw VARCHAR(160) NOT NULL,
  source_ref_id INT NULL,
  source_name_zh_tw VARCHAR(160) NOT NULL,
  probe_group_zh_tw VARCHAR(160) NOT NULL,
  probe_strength_zh_tw VARCHAR(160) NOT NULL,
  direct_monster_stat_apply INT NOT NULL,
  derived_monster_fields_zh_tw TEXT NOT NULL,
  capture_tables_zh_tw TEXT NOT NULL,
  route_tables_zh_tw TEXT NOT NULL,
  server_apply_hint_zh_tw TEXT NOT NULL,
  source_table_zh_tw VARCHAR(160) NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(128) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (source_id),
  KEY ix_xjz_monster_probe_group (probe_group_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：怪物能力逆推來源，禁止未採樣時直接改正式怪物數值。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_monster_stat_probe_priority_rules (
  rule_id INT NOT NULL,
  source_id INT NOT NULL,
  priority_rank INT NOT NULL,
  source_kind_zh_tw VARCHAR(160) NOT NULL,
  source_ref_id INT NULL,
  source_name_zh_tw VARCHAR(160) NOT NULL,
  probe_group_zh_tw VARCHAR(160) NOT NULL,
  probe_strength_zh_tw VARCHAR(160) NOT NULL,
  apply_phase_zh_tw VARCHAR(160) NOT NULL,
  primary_target_table_zh_tw VARCHAR(160) NOT NULL,
  server_handler_key_zh_tw VARCHAR(160) NOT NULL,
  direct_apply_to_monster_template INT NOT NULL,
  requires_official_sample INT NOT NULL,
  wanted_fields_zh_tw TEXT NOT NULL,
  capture_tables_zh_tw TEXT NOT NULL,
  route_tables_zh_tw TEXT NOT NULL,
  source_table_zh_tw VARCHAR(160) NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(128) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (rule_id),
  UNIQUE KEY ux_xjz_monster_probe_priority_source (source_id),
  KEY ix_xjz_monster_probe_priority_rank (priority_rank)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：怪物HP/MP/技能/能力補齊優先順序。';

DELETE FROM god2_research.xjz_monster_observation_tool_evidence;
INSERT INTO god2_research.xjz_monster_observation_tool_evidence
SELECT
  item_id,
  name_zh_tw,
  CASE tool_group
    WHEN 'enemy_hp_visibility' THEN '敵人生命值顯示'
    WHEN 'remote_view_tool' THEN '遠端查看工具'
    WHEN 'encounter_level_avoidance' THEN '遇敵等級迴避'
    WHEN 'combat_pet_growth_identification' THEN '戰寵成長鑑定'
    WHEN 'change_doll_card_copy' THEN '變身卡複製'
    WHEN 'change_doll_card_identification' THEN '變身卡鑑定'
    ELSE tool_group END,
  CASE observation_kind
    WHEN 'reveal_enemy_hp' THEN '顯示怪物目前HP'
    WHEN 'view_remote_location' THEN '遠端查看指定位置'
    WHEN 'avoid_lower_level_monsters' THEN '低等怪物不靠近'
    WHEN 'reveal_combat_pet_growth_curve' THEN '顯示戰寵成長曲線'
    WHEN 'create_monster_change_doll_card' THEN '製作怪物變身卡'
    WHEN 'reveal_card_special_ability' THEN '顯示變身卡特殊能力'
    ELSE observation_kind END,
  CASE observed_monster_field
    WHEN 'current_hp' THEN '怪物目前HP'
    WHEN 'monster_level_relative_to_user' THEN '怪物等級與玩家等級差'
    WHEN 'remote_location_visibility' THEN '遠端位置可見資訊'
    WHEN 'combat_pet_growth_curve' THEN '戰寵成長曲線'
    WHEN 'change_doll_card_from_white_name_monster' THEN '白字怪物變身卡來源'
    WHEN 'change_doll_card_special_ability' THEN '變身卡特殊能力'
    ELSE observed_monster_field END,
  server_apply_table,
  service_handler_hint,
  general_use,
  battle_use,
  use_on_other,
  NULLIF(TRIM(CONCAT_WS('；', JSON_UNQUOTE(JSON_EXTRACT(description_json, '$.description_1')), JSON_UNQUOTE(JSON_EXTRACT(description_json, '$.description_2')), JSON_UNQUOTE(JSON_EXTRACT(description_json, '$.use_effect_description')))), ''),
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_monster_observation_tool_template;

DELETE FROM god2_research.xjz_monster_observation_capture_targets;
INSERT INTO god2_research.xjz_monster_observation_capture_targets
SELECT
  target_id,
  item_id,
  name_zh_tw,
  CASE observation_kind WHEN 'reveal_enemy_hp' THEN '顯示怪物目前HP' ELSE observation_kind END,
  CASE observed_monster_field WHEN 'current_hp' THEN '怪物目前HP' ELSE observed_monster_field END,
  target_sample_table,
  target_event_table,
  action_key,
  CASE capture_priority WHEN 'highest' THEN '最高' WHEN 'high' THEN '高' WHEN 'medium' THEN '中' ELSE capture_priority END,
  required_player_action_zh_tw,
  REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(wanted_fields_json, '"monster_key"', '怪物鍵'), '"monster_name_zh_tw"', '怪物繁體名稱'), '"current_hp"', '目前HP'), '"max_hp_display_mode"', '最大HP顯示方式'), '"damage_delta"', '傷害變化量'),
  CASE reverse_probe_value WHEN 'direct_current_hp_or_hp_bar_to_max_hp' THEN '由目前HP或血條反推最大HP' ELSE reverse_probe_value END,
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_monster_observation_capture_target;

DELETE FROM god2_research.xjz_monster_stat_reverse_probe_sources;
INSERT INTO god2_research.xjz_monster_stat_reverse_probe_sources
SELECT
  source_id,
  CASE source_kind
    WHEN 'change_doll_monster_stat_group' THEN '變身卡怪物能力樣本'
    WHEN 'combat_skill_runtime_group' THEN '戰鬥技能運行樣本'
    WHEN 'monster_observation_item' THEN '怪物觀測道具'
    ELSE source_kind END,
  source_ref_id,
  source_name_zh_tw,
  CASE probe_group
    WHEN 'static_card_stat_and_identity_probe' THEN '靜態卡片能力與身分探針'
    WHEN 'combat_formula_probe' THEN '戰鬥公式探針'
    WHEN 'runtime_probe' THEN '運行中觀測探針'
    ELSE probe_group END,
  CASE probe_strength
    WHEN 'combat_formula_probe' THEN '可推導戰鬥公式'
    WHEN 'runtime_probe' THEN '可觀測運行值'
    ELSE probe_strength END,
  direct_monster_stat_apply,
  REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(derived_monster_fields_json, '"monster_key"', '怪物鍵'), '"runtime_value_json"', '運行值'), '"monster_level"', '怪物等級'), '"hp"', 'HP'), '"mp"', 'MP'), '"skill_id"', '技能ID'), '"damage_or_heal_amount"', '傷害或治療量'),
  capture_tables_json,
  route_tables_json,
  CASE
    WHEN server_apply_hint LIKE 'Use card stats%' THEN '變身卡能力只能作卡片效果與身分參考；一般怪物基礎能力仍需要官方怪物樣本。'
    WHEN server_apply_hint LIKE 'Capture controlled combat rounds%' THEN '需要控制戰鬥回合，反推物防、魔防、五行互動、狀態命中與技能行為。'
    WHEN server_apply_hint LIKE 'Use this item%' THEN '在官方流程使用此道具或效果，匯入綁定樣本後再補怪物能力缺口。'
    ELSE server_apply_hint END,
  source_table,
  raw_line,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_monster_stat_reverse_probe_source;

