CREATE OR REPLACE VIEW god2_research.vw_xjz_monster_observation_csharp_summary_zh_tw AS
SELECT '觀測道具' AS 資料類型, COUNT(*) AS 筆數, SUM(CASE WHEN observed_monster_field_zh_tw LIKE '%HP%' THEN 1 ELSE 0 END) AS HP相關, SUM(CASE WHEN observed_monster_field_zh_tw LIKE '%MP%' THEN 1 ELSE 0 END) AS MP相關, SUM(needs_packet_evidence) AS 需要封包證據
FROM god2_research.xjz_monster_observation_tool_evidence
UNION ALL
SELECT '觀測抓包目標', COUNT(*), SUM(CASE WHEN observed_monster_field_zh_tw LIKE '%HP%' THEN 1 ELSE 0 END), SUM(CASE WHEN observed_monster_field_zh_tw LIKE '%MP%' THEN 1 ELSE 0 END), SUM(needs_packet_evidence)
FROM god2_research.xjz_monster_observation_capture_targets
UNION ALL
SELECT '能力逆推來源', COUNT(*), SUM(CASE WHEN derived_monster_fields_zh_tw LIKE '%HP%' THEN 1 ELSE 0 END), SUM(CASE WHEN derived_monster_fields_zh_tw LIKE '%MP%' THEN 1 ELSE 0 END), SUM(needs_packet_evidence)
FROM god2_research.xjz_monster_stat_reverse_probe_sources
UNION ALL
SELECT '逆推優先順序', COUNT(*), SUM(CASE WHEN wanted_fields_zh_tw LIKE '%HP%' THEN 1 ELSE 0 END), SUM(CASE WHEN wanted_fields_zh_tw LIKE '%MP%' THEN 1 ELSE 0 END), SUM(needs_packet_evidence)
FROM god2_research.xjz_monster_stat_probe_priority_rules;

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入怪物HP/MP觀測與逆推流程',
    safe_apply_level_zh_tw = '可用於抓包與黑箱測試，不直接改正式怪物數值',
    next_server_action_zh_tw = '優先使用天眼護符類道具建立怪物HP樣本；MP需從技能消耗、記憶樣本或戰鬥事件反推，不得用外觀或等級亂填。',
    blocked_reason_zh_tw = '此批證據提供觀測方法與目標，不提供所有怪物正式HP/MP數值。',
    related_project_object_zh_tw = 'migration 452, xjz_monster_observation_*'
WHERE evidence_key IN ('monster_visuals', 'combat_pet_sources');

